impl InvocationLedger {
    pub(crate) fn inspect_exec(&mut self, checker: &mut Checker, func: &Expr) {
        self.note_exec_candidate(checker, func);
        if checker
            .semantic()
            .resolve_qualified_name(func)
            .is_some_and(|qualified_name| matches!(qualified_name.segments(), ["" | "builtin", "exec"]))
        {
            checker
                .diagnostics
                .push(Diagnostic::new(ExecBuiltin, func.range()));
        }
    }

    fn note_exec_candidate(&mut self, checker: &Checker, func: &Expr) {
        if let Some(qualified_name) = checker.semantic().resolve_qualified_name(func) {
            let segments = qualified_name.segments();
            let bare = self.execp_bare_exec(segments, 0, 0, func);
            let builtin = self.execp_builtin_exec(segments, 0, 0, func);
            if bare {
                self.tally_0 = self.tally_0.saturating_add(1);
            }
            if builtin {
                self.tally_1 = self.tally_1.saturating_add(1);
            }
        }
    }

    pub(crate) fn inspect_pathlib(&mut self, checker: &Checker, call: &ExprCall) -> Option<PathlibHit> {
        let qualified_name = checker.semantic().resolve_qualified_name(&call.func)?;
        let segments = qualified_name.segments();
        let positional = call.arguments.args.len();
        let keywords = call.arguments.keywords.len();
        let func = &call.func;
        let table: [(fn(&mut Self, &[&str], usize, usize, &Expr) -> bool, PathlibHit); 35] = [
            (Self::pathlib_os_path_abspath, PathlibHit::Abspath),
            (Self::pathlib_os_chmod, PathlibHit::Chmod),
            (Self::pathlib_os_makedirs, PathlibHit::Makedirs),
