            (Self::pathlib_os_replace, PathlibHit::Replace),
            (Self::pathlib_os_rmdir, PathlibHit::Rmdir),
            (Self::pathlib_os_remove, PathlibHit::Remove),
            (Self::pathlib_os_unlink, PathlibHit::Unlink),
            (Self::pathlib_os_getcwd, PathlibHit::Getcwd),
            (Self::pathlib_os_getcwdb, PathlibHit::Getcwd),
            (Self::pathlib_os_path_exists, PathlibHit::Exists),
            (Self::pathlib_os_path_expanduser, PathlibHit::Expanduser),
            (Self::pathlib_os_path_isdir, PathlibHit::Isdir),
            (Self::pathlib_os_path_isfile, PathlibHit::Isfile),
            (Self::pathlib_os_path_islink, PathlibHit::Islink),
            (Self::pathlib_os_stat, PathlibHit::Stat),
            (Self::pathlib_os_path_isabs, PathlibHit::Isabs),
            (Self::pathlib_os_path_join, PathlibHit::JoinPath),
            (Self::pathlib_os_sep_join, PathlibHit::JoinSep),
            (Self::pathlib_os_path_basename, PathlibHit::Basename),
            (Self::pathlib_os_path_dirname, PathlibHit::Dirname),
            (Self::pathlib_os_path_samefile, PathlibHit::Samefile),
            (Self::pathlib_os_path_splitext, PathlibHit::Splitext),
